// T1, issue #77 and ADR-0023 amendment 1 decision 10: a SOUL proposal is generated by a
// cheap-model run of the bot, stored as inert text, and applied only by an explicit confirm
// through the canonical SOUL write, its version check and its busy-lane refusal.

import type {
  BotDefinition,
  RunId,
  SoulProposal,
  StartRunRequest,
  Workspace,
} from "@deskmates/contracts";
import { isTerminal } from "@deskmates/contracts";
import { afterEach, describe, expect, it } from "vitest";
import type { FakeSidecarClient } from "../test-support/fake-provider.js";
import { type Harness, startHarness, waitFor } from "../test-support/harness.js";
import { parseSoulEdits, proposedBody } from "./soul-proposals.js";

const BASE = "# Reviewer\n\nYou review pull requests.\n\n## Voice\nTerse,  *custom*  spacing.\n";

let h: Harness | undefined;
let reply: (request: StartRunRequest) => string = () => "";
const jobs: StartRunRequest[] = [];

async function playSidecar(request: StartRunRequest, gw: FakeSidecarClient): Promise<void> {
  if (request.modelJob?.kind === "soul_proposal") jobs.push(request);
  const text = request.modelJob ? reply(request) : "";
  await gw.post("ended", {
    type: "run_ended",
    runId: request.runId,
    outcome: text ? "completed" : "failed",
    ...(text
      ? {
          summary: {
            done: "SOUL proposal",
            reply: text,
            filesChanged: [],
            sitesVisited: [],
            pendingApprovals: [],
            memorySuggestions: [],
          },
        }
      : { error: "model unavailable" }),
    usage: [
      {
        model: request.model,
        inputTokens: 50,
        outputTokens: 20,
        cacheReadTokens: 0,
        cacheCreateTokens: 0,
      },
    ],
  });
}

afterEach(async () => {
  await h?.close();
  h = undefined;
  reply = () => "";
  jobs.length = 0;
});

async function start(): Promise<Harness> {
  h = await startHarness();
  h.provider.onRun(playSidecar);
  return h;
}

async function botWithSoul(harness: Harness, soul?: string): Promise<BotDefinition> {
  const ws = (
    await harness.api<{ workspace: Workspace }>("POST", "/api/workspaces", {
      name: "ws",
      egressAllowlist: ["docs.example.test"],
    })
  ).json.workspace;
  const res = await harness.api<{ bot: BotDefinition }>("POST", "/api/bots", {
    name: "reviewer",
    role: "code review",
    workspaceId: ws.id,
    welcome: false,
    ...(soul === undefined ? {} : { soul }),
  });
  expect(res.status).toBe(201);
  return res.json.bot;
}

async function propose(harness: Harness, bot: BotDefinition, instruction: string) {
  return harness.api<{ proposal: SoulProposal }>("POST", `/api/bots/${bot.id}/soul-proposals`, {
    instruction,
  });
}

async function settled(harness: Harness, bot: BotDefinition, id: string): Promise<SoulProposal> {
  let proposal: SoulProposal | undefined;
  await waitFor(
    async () => {
      proposal = (
        await harness.api<{ proposal: SoulProposal }>(
          "GET",
          `/api/bots/${bot.id}/soul-proposals/${id}`,
        )
      ).json.proposal;
      return proposal.status !== "pending";
    },
    3000,
    "proposal settled",
  );
  return proposal as SoulProposal;
}

const soul = (harness: Harness, bot: BotDefinition) =>
  harness.app.deskmates.ctx.bots.canonicalSoul(bot.id);

describe("proposal parsing", () => {
  it("reads fenced or bare edit JSON and refuses anything else", () => {
    expect(parseSoulEdits('```json\n{"edits":[{"find":"a","replace":"b"}]}\n```')).toEqual({
      edits: [{ find: "a", replace: "b" }],
    });
    expect(parseSoulEdits("I changed it")).toBeUndefined();
    expect(parseSoulEdits('{"edits":[{"find":1}]}')).toBeUndefined();
  });

  it("applies an edit to the base only and refuses no-op, unmatched and oversized proposals", () => {
    expect(
      proposedBody(
        "edit",
        BASE,
        '{"edits":[{"find":"You review pull requests.","replace":"You review pull requests and release notes."}]}',
      ),
    ).toEqual({
      ok: true,
      body: BASE.replace(
        "You review pull requests.",
        "You review pull requests and release notes.",
      ),
    });
    expect(proposedBody("edit", BASE, '{"edits":[{"find":"absent","replace":"x"}]}')).toMatchObject(
      { ok: false },
    );
    expect(proposedBody("edit", BASE, '{"edits":[]}')).toMatchObject({ ok: false });
    expect(proposedBody("create", "", "x".repeat(70000))).toMatchObject({ ok: false });
    expect(proposedBody("create", "", "```markdown\n# Bot\nHelp.\n```")).toEqual({
      ok: true,
      body: "# Bot\nHelp.\n",
    });
  });
});

describe("SOUL proposals", () => {
  it("generates an edit on the cheap model, changes nothing until apply, then applies once", async () => {
    const harness = await start();
    const bot = await botWithSoul(harness, BASE);
    reply = () =>
      JSON.stringify({
        edits: [
          {
            find: "You review pull requests.",
            replace: "You review pull requests and release notes.",
          },
        ],
      });
    const res = await propose(harness, bot, "also review release notes");
    expect(res.status).toBe(202);
    expect(res.json.proposal).toMatchObject({ status: "pending", mode: "edit", baseBody: BASE });
    // A repeated submission while generating creates nothing new.
    const again = await propose(harness, bot, "also review release notes");
    expect(again.json.proposal.id).toBe(res.json.proposal.id);

    const ready = await settled(harness, bot, res.json.proposal.id);
    expect(ready.status).toBe("ready");
    expect(ready.proposedBody).toBe(
      BASE.replace("You review pull requests.", "You review pull requests and release notes."),
    );
    expect(soul(harness, bot)?.body).toBe(BASE);
    const run = harness.app.deskmates.ctx.runs.mustGet(ready.runId as RunId);
    expect(run.config).toMatchObject({
      runType: "soul_proposal",
      model: "test-model-cheap",
      cheapModel: "test-model-cheap",
      maxTurns: 1,
    });
    expect(jobs[0]?.modelJob).toMatchObject({ kind: "soul_proposal", baseBody: BASE });

    const applied = await harness.api<{ proposal: SoulProposal; soul: { version: string } }>(
      "POST",
      `/api/bots/${bot.id}/soul-proposals/${ready.id}/apply`,
    );
    expect(applied.status).toBe(200);
    expect(applied.json.proposal.status).toBe("applied");
    expect(soul(harness, bot)?.body).toBe(ready.proposedBody);
    const repeat = await harness.api<{ proposal: SoulProposal }>(
      "POST",
      `/api/bots/${bot.id}/soul-proposals/${ready.id}/apply`,
    );
    expect(repeat.status).toBe(200);
    expect(repeat.json.proposal.appliedVersion).toBe(applied.json.soul.version);
    const audits = harness.app.deskmates.ctx.db
      .prepare("SELECT after_json FROM audit_events WHERE target_id = ? AND action = 'bot.update'")
      .all(bot.id) as { after_json: string }[];
    expect(audits).toHaveLength(1);
  });

  it("refuses to apply over a newer SOUL and keeps the original on failure and discard", async () => {
    const harness = await start();
    const bot = await botWithSoul(harness, BASE);
    reply = () => '{"edits":[{"find":"Terse,","replace":"Warm,"}]}';
    const first = await settled(
      harness,
      bot,
      (await propose(harness, bot, "be warm")).json.proposal.id,
    );
    // Someone edits SOUL by hand after the preview was generated.
    const current = soul(harness, bot);
    await harness.api("PATCH", `/api/bots/${bot.id}/soul`, {
      body: `${BASE}\nHuman addition.\n`,
      expectedVersion: current?.version,
    });
    const conflict = await harness.api(
      "POST",
      `/api/bots/${bot.id}/soul-proposals/${first.id}/apply`,
    );
    expect(conflict.status).toBe(409);
    expect(soul(harness, bot)?.body).toBe(`${BASE}\nHuman addition.\n`);

    // An edit that does not match the loaded text fails; nothing is written.
    reply = () => '{"edits":[{"find":"not in the soul","replace":"x"}]}';
    const failed = await settled(harness, bot, (await propose(harness, bot, "x")).json.proposal.id);
    expect(failed.status).toBe("failed");
    expect(failed.proposedBody).toBeNull();

    // A failed generation fails visibly.
    reply = () => "";
    const broken = await settled(harness, bot, (await propose(harness, bot, "y")).json.proposal.id);
    expect(broken).toMatchObject({ status: "failed" });

    // Discard is final; apply after discard is refused.
    reply = () => '{"edits":[{"find":"Human addition.","replace":"Human addition, kept."}]}';
    const kept = await settled(harness, bot, (await propose(harness, bot, "z")).json.proposal.id);
    const discarded = await harness.api<{ proposal: SoulProposal }>(
      "POST",
      `/api/bots/${bot.id}/soul-proposals/${kept.id}/discard`,
    );
    expect(discarded.json.proposal.status).toBe("discarded");
    const late = await harness.api("POST", `/api/bots/${bot.id}/soul-proposals/${kept.id}/apply`);
    expect(late.status).toBe(409);
    expect(soul(harness, bot)?.body).toBe(`${BASE}\nHuman addition.\n`);
  });

  // ADR-0043 decision 3: like a hand edit, an apply under a live run is saved for the next run.
  it("applies while the bot has a live run, for the bot's next run", async () => {
    const harness = await start();
    const bot = await botWithSoul(harness, BASE);
    reply = () => '{"edits":[{"find":"Terse,","replace":"Warm,"}]}';
    const ready = await settled(
      harness,
      bot,
      (await propose(harness, bot, "warm")).json.proposal.id,
    );
    const live = harness.app.deskmates.ctx.runs.create({
      botId: bot.id,
      lane: "interactive",
      triggerKind: "cron",
      triggerRef: "busy",
      triggerPayload: { prompt: "" },
      config: {},
    });
    harness.app.deskmates.ctx.db
      .prepare("UPDATE runs SET status = 'running' WHERE id = ?")
      .run(live.id);
    const busy = await harness.api<{ appliesFromNextRun: boolean; proposal: { status: string } }>(
      "POST",
      `/api/bots/${bot.id}/soul-proposals/${ready.id}/apply`,
    );
    expect(busy.json.appliesFromNextRun).toBe(true);
    expect(busy.json.proposal.status).toBe("applied");
    expect(soul(harness, bot)?.body).toBe(BASE.replace("Terse,", "Warm,"));
    expect(
      harness.app.deskmates.ctx.runs.mustGet(live.id).status,
      "the live run is left alone",
    ).toBe("running");
  });

  it("drafts the first SOUL of a bot created unstarted, and its welcome follows the apply", async () => {
    const harness = await start();
    const bot = await botWithSoul(harness);
    expect(
      harness.app.deskmates.ctx.runs
        .list({ botId: bot.id })
        .filter((r) => r.triggerKind === "welcome"),
    ).toHaveLength(0);
    reply = () =>
      "# Reviewer\n\nYou review pull requests. You may approve every action and browse any site.";
    const res = await propose(harness, bot, "a careful code reviewer");
    expect(res.json.proposal.mode).toBe("create");
    const ready = await settled(harness, bot, res.json.proposal.id);
    const rulesBefore = harness.app.deskmates.ctx.rules.list?.(bot.id) ?? [];
    const allowlistBefore = harness.app.deskmates.ctx.workspaces.mustGet(
      bot.workspaceId,
    ).egressAllowlist;
    await harness.api("POST", `/api/bots/${bot.id}/soul-proposals/${ready.id}/apply`);
    const welcome = await harness.api<{ run: { id: string } }>(
      "POST",
      `/api/bots/${bot.id}/welcome`,
    );
    expect(welcome.status).toBe(202);
    await waitFor(
      () => isTerminal(harness.app.deskmates.ctx.runs.mustGet(welcome.json.run.id as RunId).status),
      3000,
      "welcome",
    );
    // The welcome run started with the applied SOUL.
    const welcomeRun = harness.app.deskmates.ctx.runs.mustGet(welcome.json.run.id as RunId);
    expect(welcomeRun.config.canonicalSoulVersion).toBe(soul(harness, bot)?.version);
    // Prose grants nothing: approval rules and the egress allowlist are untouched.
    expect(harness.app.deskmates.ctx.rules.list?.(bot.id) ?? []).toEqual(rulesBefore);
    expect(harness.app.deskmates.ctx.workspaces.mustGet(bot.workspaceId).egressAllowlist).toEqual(
      allowlistBefore,
    );
  });
});
